class TaskDataProcessor {
    constructor(tasks) {
        this.tasks = tasks;
    }

    process() {
        return this.tasks.map(task => ({
            name: task.name,
            status: task.completed ? "Completed" : "Pending",
            duration: task.durationHours
        }));
    }
}

class ReportRenderer {
    render(processedData) {
        let reportString = "# Task Status Report\n\n";
        processedData.forEach(item => {
            reportString += `- **${item.name}**: ${item.status} (${item.duration} hours)\n`;
        });
        return reportString;
    }
}

class ReportExporter {
    export(reportContent) {
        console.log(reportContent);
    }
}

// Example usage
const myTasks = [
    { name: "Design Database", completed: true, durationHours: 8 },
    { name: "Implement API", completed: false, durationHours: 20 },
    { name: "Write Tests", completed: false, durationHours: 10 }
];

const processor = new TaskDataProcessor(myTasks);
const processedReportData = processor.process();

const renderer = new ReportRenderer();
const finalReport = renderer.render(processedReportData);

const exporter = new ReportExporter();
exporter.export(finalReport);

